import{z as o,x as s,o as n,c as p,q as r,j as i,D as E,d as t,s as A,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"账面价值与无形资产","description":"","frontmatter":{"title":"账面价值与无形资产","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/book-intangibles.md","filePath":"quant/book-intangibles.md","lastUpdated":1791063341000}'),d={name:"quant/book-intangibles.md"};function m(F,a,h,C,c,u){const B=s("Mermaid");return n(),p("div",null,[a[2]||(a[2]=r('<h1 id="账面价值与无形资产" tabindex="-1">账面价值与无形资产 <a class="header-anchor" href="#账面价值与无形资产" aria-label="Permalink to &quot;账面价值与无形资产&quot;">​</a></h1><div class="epigraph"><p>账面权益是会计方程的残差，不是重置成本；研发与品牌大多费用化，于是「便宜」可能只是账上缺了一块资产。</p><footer>—— 据 Penman, Financial Statement Analysis；Fama and French, Journal of Financial Economics, 1993 对账面权益的构造整理</footer></div><p>上一课<a href="/quant/earnings-quality">盈利质量</a>把利润拆成更可持续与更易反转的部分。价值因子用的却是账面权益对市值。账面从<a href="/quant/three-statements-link">三张表怎么连</a>的权益链来，但权益里缺什么、多了什么，会让 HML 排序比较的不是同一类经济资产。本课只补账面作为因子输入时的缺口，不重写质量定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Fama–French 的 HML 用 Compustat 账面权益配 CRSP 市值，并在六月形成组合。账面是会计恒等式里的残差：资产减负债减优先股等。研发、广告、人力资本在多数准则下费用化，不进资产，于是知识密集公司账面偏低、账面市值偏高，看起来像成长。反过来，外购商誉进账面，自制品牌不进，并购活跃的公司账面被抬高。缺口是：价值排序在比较<strong>可确认的会计净资产</strong>，不是比较经济净资产。</p><p><span class="marginnote">术语翻译：HML（High Minus Low）是 Fama–French 的价值因子——按「账面权益 ÷ 市值」给股票排序，做多最高的一档（账面相对市值便宜的价值股）、做空最低的一档（贵的成长股）。名字里的 High/Low，指的就是这个比值的高低。</span></p><p>后课因子来源课会问字段从哪张表取；本课先承认账面不是通用价值尺度，尤其当无形资产占比随行业变化。</p><h3 id="账面低不是一定低估" tabindex="-1">账面低不是一定低估 <a class="header-anchor" href="#账面低不是一定低估" aria-label="Permalink to &quot;账面低不是一定低估&quot;">​</a></h3><p>低账面市值可以是便宜，也可以是账上没记的无形资产、多年亏损把权益蚀空、或即将退市的残值。质量课已经提示便宜与低质量共线。本课补的是计量：即使利润可持续，账面仍可能因为费用化规则而系统性偏低。用行业中性化或无形资产调整，是承认尺度，不是否定价值溢价。</p><p><span class="marginnote">数字实例：两家公司市值都是 100 亿。A 研发年年费用化，账面 20 亿，账面市值比 0.2；B 靠并购扩张，商誉进了账面，账面 35 亿，比值 0.35。若两家的专利、品牌经济上差不多，HML 却会把 A 划进「成长」、把 B 划进「价值」——排序比的是会计残差，不是经济资产。</span></p><p><span class="marginnote">Lev 等人强调费用化研发会压低账面、压低当期利润并抬高后续利润。价值与盈利因子会同时被这套会计触及。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>因子用的账面，取 PIT 下当时可用的股东权益，按 Fama–French 惯例调整优先股、并视情况加回递延税与一些储备——细节以你锁定的构造说明为准，不要混用「最新总权益」。市值用形成日的价格乘当时股本，股本口径与下一课稀释一致。</p><p>若要减弱无形资产扭曲，常用做法是行业内排序（Fama–French 48 或 GICS），或把累积研发费用资本化后加回账面。后者引入自己的可用日期与摊销假设，必须写进 PIT：不能用今天的研发资本化规则回填二十年。本课不把资本化做成标准定义，只把它标成对账面尺度的可选修正。</p>',14)),(n(),i(l,null,{default:E(()=>[A(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20BS%5B%22%E8%B5%84%E4%BA%A7%E8%B4%9F%E5%80%BA%E8%A1%A8%E6%9D%83%E7%9B%8A%22%5D%20--%3E%20BE%5B%22%E8%B4%A6%E9%9D%A2%E6%9D%83%E7%9B%8A%22%5D%0A%20%20EXP%5B%22%E7%A0%94%E5%8F%91%E5%B9%BF%E5%91%8A%E8%B4%B9%E7%94%A8%E5%8C%96%22%5D%20--%3E%20BE%0A%20%20GW%5B%22%E5%A4%96%E8%B4%AD%E5%95%86%E8%AA%89%22%5D%20--%3E%20BE%0A%20%20BE%20--%3E%20HML%5B%22%E8%B4%A6%E9%9D%A2%E5%B8%82%E5%80%BC%E6%8E%92%E5%BA%8F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"研发资本化是可选修正，必须自带摊销年限与 PIT，不能回写进官方 HML。负账面留在宇宙并排除出价值端，规则写死。行业中性吸收费用化差异，不在个股上估品牌。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"价值溢价的经验结果建立在「会计账面 / 市值」上，不是建立在「重置成本 / 市值」上。会计账面漏记自制无形资产时，排序把科技与消费品牌推进成长端；把并购商誉记进去时，又把收购方推进价值端。行业中性是最便宜的修补：在可比会计规则内比相对便宜。后课行业分类就是为这件事服务，不是为了 macro 故事。",-1)),(n(),i(l,null,{default:E(()=>[A(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E4%B8%A4%E5%AE%B6%E5%85%AC%E5%8F%B8%EF%BC%9A%E7%BB%8F%E6%B5%8E%E8%B5%84%E4%BA%A7%E5%87%A0%E4%B9%8E%E7%9B%B8%E5%90%8C%22%5D%20--%3E%20C1%5B%22A%EF%BC%9A%E7%A0%94%E5%8F%91%E5%85%A8%E9%83%A8%E8%B4%B9%E7%94%A8%E5%8C%96%EF%BC%8C%E6%97%A0%E5%B9%B6%E8%B4%AD%22%5D%0A%20%20E%20--%3E%20C2%5B%22B%EF%BC%9A%E8%87%AA%E7%A0%94%E5%B0%91%EF%BC%8C%E9%9D%A0%E5%B9%B6%E8%B4%AD%E6%89%A9%E5%BC%A0%22%5D%0A%20%20C1%20--%3E%20B1%5B%22%E8%B4%A6%E9%9D%A2%E5%81%8F%E4%BD%8E%EF%BC%8C%E7%9C%8B%E8%B5%B7%E6%9D%A5%E5%83%8F%E6%88%90%E9%95%BF%22%5D%0A%20%20C2%20--%3E%20B2%5B%22%E5%95%86%E8%AA%89%E6%8A%AC%E9%AB%98%E8%B4%A6%E9%9D%A2%EF%BC%8C%E7%9C%8B%E8%B5%B7%E6%9D%A5%E5%83%8F%E4%BB%B7%E5%80%BC%22%5D%0A%20%20B1%20--%3E%20S%5B%22HML%20%E6%8E%92%E5%BA%8F%E9%94%99%E4%BD%8D%EF%BC%9A%E6%AF%94%E8%BE%83%E7%9A%84%E4%B8%8D%E6%98%AF%E5%90%8C%E7%B1%BB%E8%B5%84%E4%BA%A7%22%5D%0A%20%20B2%20--%3E%20S%0A%20%20S%20--%3E%20F%5B%22%E4%BF%AE%E8%A1%A5%EF%BC%9A%E8%A1%8C%E4%B8%9A%E5%86%85%E6%8E%92%E5%BA%8F%E6%88%96%E7%A0%94%E5%8F%91%E8%B5%84%E6%9C%AC%E5%8C%96%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">账面可以是负的。负账面公司常被踢出 HML 的价值端或单独处理；无声丢弃会再造幸存者。</span></p><p>复制 HML 时，账面取当时年报权益并按说明书调整优先股，市值取形成日；负账面剔除出价值端但留在宇宙以便报告覆盖。若做研发资本化，摊销年限与可用日期写进同一张来源卡，切勿用今日市值高的科技公司「反推」它们早该被资本化的账面。行业中性是默认修补：在 FF48 或 GICS 内比相对账面市值，避免把会计规则差写成价值溢价。</p><p><span class="marginnote">常见误区：看到账面市值比低就喊「低估」。低也可能因为账上没记无形资产、连年亏损把权益蚀空、或公司快退市只剩残值——便宜与低质量常常共线。先问这块账面缺了什么，再谈便宜。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写无形资产会计准则全文，不估品牌估值模型。商誉减值下一课之后才专讲；股份稀释影响的是市值分母与每股账面，下一课补。后课默认：价值因子的账面是 PIT 会计权益，已知其对自制无形资产有偏，比较默认在行业内或有记录的调整规则下进行。</p><p>后课股份稀释会改市值分母，本课的账面分子保持会计权益。不要用「无形资产调整后的经济账面」去复制 French 库还声称一致。负账面、金融股是否入 HML，整段样本只执行一种说明书。自制品牌不进账面这件事，用行业中性吸收，而不是在个股上估一个品牌市值。</p><p>账面市值比较的是会计净资产对市值，不是重置成本；后课默认价值排序在行业内或有记录的无形资产规则下进行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>账面是会计残差，不是经济净资产。</li><li>费用化无形资产让知识密集公司看起来像成长。</li><li>Fama–French 的 HML 用的就是这块会计账面，六月形成。</li><li>行业内排序是尺度修补；资本化研发必须自己遵守 PIT。</li><li>负账面要有规则，不能静默删除。</li><li>出处：Penman；Fama and French (1993)；无形资产与研发费用化文献（Lev 等）。</li></ul>',9))])}const b=o(d,[["render",m]]);export{f as __pageData,b as default};
